import sys
import os
import base64
import hashlib
import subprocess
import shutil

OUTPUT_DIR = "delivery_output"
gen_id = "DB-G0001"
transcript_log = []

def log(msg):
    print(msg)
    transcript_log.append(msg)

def main():
    log(f"Starting generation: {gen_id}")

    # Clean state
    if os.path.exists(OUTPUT_DIR):
        shutil.rmtree(OUTPUT_DIR)
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    log("State: Clean state. Empty output directory created.")

    # The ELF byte stream (generated earlier to include the python GUI analyzer and run natively)
    b64_data = ""

    log(f"Byte-stream length: {len(b64_data)} (base64 chars)")

    bin_path = os.path.join(OUTPUT_DIR, "fs_analyzer.elf")
    bin_data = base64.b64decode(b64_data)
    with open(bin_path, "wb") as f:
        f.write(bin_data)
    os.chmod(bin_path, 0o755)

    log(f"Executable decoded and saved to {bin_path}")

    sha256_hash = hashlib.sha256(bin_data).hexdigest()
    log(f"SHA-256 Hash immediately after decoding: {sha256_hash}")

    manifest_path = os.path.join(OUTPUT_DIR, "manifest.txt")
    with open(manifest_path, "w") as f:
        f.write(f"Generation: {gen_id}\n")
        f.write(f"Executable: fs_analyzer.elf\n")
        f.write(f"SHA-256: {sha256_hash}\n")

    log(f"Manifest written to {manifest_path}")

    # Test the generation
    log("Testing the generation...")
    test_target = "test_fixture_dir"
    if os.path.exists(test_target):
        shutil.rmtree(test_target)
    os.makedirs(test_target, exist_ok=True)
    with open(os.path.join(test_target, "file1.txt"), "w") as f:
        f.write("A" * 100)
    with open(os.path.join(test_target, "file2.txt"), "w") as f:
        f.write("B" * 250)
    os.makedirs(os.path.join(test_target, "subdir"), exist_ok=True)
    with open(os.path.join(test_target, "subdir", "file3.txt"), "w") as f:
        f.write("C" * 10)

    test_report = os.path.join(OUTPUT_DIR, "test_report.txt")
    cmd = [os.path.abspath(bin_path), os.path.abspath(test_target), os.path.abspath(test_report)]
    result = subprocess.run(cmd, capture_output=True, text=True, cwd=OUTPUT_DIR)

    log(f"Test execution finished with return code {result.returncode}")
    log(f"Test stdout: {result.stdout.strip()}")
    if result.stderr.strip():
        log(f"Test stderr: {result.stderr.strip()}")

    if os.path.exists(test_report):
        with open(test_report, "r") as f:
            report_content = f.read()

        log(f"Test Report Content:\n{report_content}")

        if "Files: 3" in report_content and "Total Size: 360" in report_content:
            log("Validation test: PASSED")
        else:
            log("Validation test: FAILED")
    else:
        log("Validation test: FAILED (report not found)")

    # Clean up test fixture
    shutil.rmtree(test_target)

    # Transcript
    transcript_path = os.path.join(OUTPUT_DIR, "transcript.txt")
    with open(transcript_path, "w") as f:
        f.write("\n".join(transcript_log))

    log(f"Transcript written to {transcript_path}")
    print("Done. Deliverables are in the delivery_output directory.")

if __name__ == "__main__":
    main()
